 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return {};
  }

  // Define column references
  auto visit_time_col = "visit_time"_c;
  auto url_col = "url"_c;
  auto visit_date_col = "visit_date"_c;

  // Extract date from visit_time by concatenating year, month, and day
  // This simulates strftime('%Y-%m-%d', visit_time)
  auto visit_date_expr = concat(
    cast<std::string>(year(visit_time_col)), 
    "-",
    cast<std::string>(month(visit_time_col)),
    "-", 
    cast<std::string>(day(visit_time_col))
  ) | as<"visit_date">;

  // Build and execute the query
  auto result = conn | select_from<PageVisit>(
    visit_date_expr,
    count() | as<"total_visits">,
    count_distinct(url_col) | as<"unique_pages">
  )
  | group_by(visit_date_col)
  | order_by(visit_date_col)
  | to<std::vector<DailyTraffic>>;

  // Return the result or empty vector on error
  if (result) {
    return *result;
  }
  return {};
}

}  // namespace query_daily_traffic_metrics
