  PrimaryKey<int> product_id;
  std::string category;
  static constexpr const char* tablename = "Product";
};

struct Sale {
  PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  double amount;
  static constexpr const char* tablename = "Sale";
};

struct CategoryReport {
  std::string category;
  int total_qty;
  double total_amt;
