struct ProductSalesReport {
  static constexpr const char* tablename = "ProductSalesReport";
  static constexpr bool is_view = true;
  std::string category;
  int total_qty;
  double total_amt;
};

std::vector<CategoryReport> query_product_sales_report() {
    using namespace sqlgen;

    // Connect to SQLite database
    auto conn_result = sqlite::connect("test_db.sqlite");

    if (!conn_result) {
        return {};  // Return empty vector on connection error
    }

    auto conn = *conn_result;

    // Build the query:
    // SELECT p.category, SUM(s.quantity) as total_qty, SUM(s.amount) as total_amt
    // FROM Product p
    // INNER JOIN Sale s ON p.product_id = s.product_id
    // GROUP BY p.category
    // HAVING total_amt > 5000
    auto query = select_from<Product, "p">(
        col<"category", "p">,
        sum(col<"quantity", "s">) | as<"total_qty">,
        sum(col<"amount", "s">) | as<"total_amt">
    ) 
    | inner_join<Sale, "s">(col<"product_id", "p"> == col<"product_id", "s">)
    | group_by(col<"category", "p">)
    | where(sum(col<"amount", "s">) > 5000.0)
    | to<std::vector<CategoryReport>>;

    // Execute query
    auto result = query(conn);

    if (!result) {
        return {};  // Return empty vector on query error
    }

    return *result;
}

}  // namespace query_product_sales_report
