struct Document {
  PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    // Handle empty list case
    if (ids.empty()) {
        return true;
    }

    // Connect to SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn) {
        return false;
    }

    // Build UPDATE statement with IN clause
    std::string sql = "UPDATE Document SET is_deleted = 1, deleted_at = CURRENT_TIMESTAMP WHERE doc_id IN (";
    for (size_t i = 0; i < ids.size(); ++i) {
        if (i > 0) {
            sql += ",";
        }
        sql += std::to_string(ids[i]);
    }
    sql += ")";

    // Execute the update statement
    auto result = conn | sqlgen::exec(sql);

    // Return success status
    return result.has_value();
}

}  // namespace soft_delete_records
