  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the SELECT query for the view
  // Sale is t1 (first table), Product is t2 (joined table)
  auto query = select_from<Sale>(
    "name"_t2 | as<"product_name">,              // Product.name as product_name
    sum("quantity"_t1) | as<"total_quantity">,   // SUM(Sale.quantity) as total_quantity
    sum("amount"_t1) | as<"total_revenue">       // SUM(Sale.amount) as total_revenue
  )
  | join<Product>("product_id"_t1 == "product_id"_t2)  // JOIN Product ON Sale.product_id = Product.product_id
  | group_by("name"_t2);                                // GROUP BY Product.name

  // Create or replace the view
  auto result = create_or_replace_view_as<SalesSummary>(query)(conn);

  return result.has_value();
}

