        transpilation::to_select_from<TableTupleType, AliasType, FieldsType,
                                      TableOrQueryType, JoinsType, WhereType,
                                      GroupByType, OrderByType, LimitType>(
            _query.fields_, _query.from_, _query.joins_, _query.where_,
            _query.limit_));
