#include <vector>
#include <string>

namespace analyze_social_network {

struct User {
  PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");

  if (!conn_result) {
    return {};
  }

  auto conn = *conn_result;

  // Create tables
  auto create_result = conn 
    | create_table<User>{.if_not_exists_ = true}
    | create_table<Friendship>{.if_not_exists_ = true};

  if (!create_result) {
    return {};
  }

  // Insert user data
  for (const auto& user : users) {
    auto insert_result = create_result | insert(user);
    if (!insert_result) {
      continue;
    }
    create_result = insert_result;
  }

  // Insert friendship data
  for (const auto& friendship : friendships) {
    auto insert_result = create_result | insert(friendship);
    if (!insert_result) {
      continue;
    }
    create_result = insert_result;
  }

  // Query to find mutual friends using SELF-JOIN
  // Find pairs of users who are friends and share at least one mutual friend
  auto query = select_from<User, "u1">(
    col<"username", "u1"> | as<"user1_name">,
    col<"username", "u2"> | as<"user2_name">
  )
  | inner_join<Friendship, "f1">(
      col<"user_id", "u1"> == col<"user1_id", "f1">
  )
  | inner_join<Friendship, "f2">(
      col<"user2_id", "f1"> == col<"user1_id", "f2">
  )
  | inner_join<User, "u2">(
      col<"user2_id", "f2"> == col<"user_id", "u2">
  )
  | where(
      col<"user_id", "u1"> < col<"user_id", "u2">
  )
  | to<std::vector<FriendConnection>>;

  // Execute query and collect results
  auto query_result = create_result | query;

  std::vector<FriendConnection> results;
  if (query_result) {
    results = *query_result;
  }

  return results;
}

}  // namespace analyze_social_network
