  friend auto operator-(const Operation& _op1, const T& _op2) noexcept {
    if constexpr (is_duration_v<T>) {
      using DurationType = std::remove_cvref_t<T>;
      return _op1 + DurationType(_op2.count() * (-1));

    } else {
