    using OtherType = typename transpilation::ToTranspilationType<
        std::remove_cvref_t<T>>::Type;

    return Operation<Operator::plus, Aggregation, OtherType>{
        .operand1 = _op1, .operand2 = to_transpilation_type(_op2)};
