    using T = std::remove_cvref_t<decltype(*this)>;
    return transpilation::As<T, _new_name>{.val = *this};
  }

  /// Returns an IS NULL condition.
  auto is_null() const noexcept {
    return make_condition(conditions::is_null(*this));
