using namespace sqlgen;

namespace join_orders_customers_payments {

struct Customer {
  PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  PrimaryKey<int> order_id;
  int customer_id;
  Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct Payment {
  PrimaryKey<int> payment_id;
  int order_id;
  double amount;
};

struct Consolidated {
  PrimaryKey<int> order_id;
  std::string customer_name;
  double amount;
};

/**
 * description: join_orders_customers_payments.
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build query: select from Order, join Customer and Payment, order by amount desc
  auto query = select_from<Order, "t1">(
      "order_id"_t1,
      "name"_t2 | as<"customer_name">,
      "amount"_t3
    )
    | inner_join<Customer, "t2">("customer_id"_t1 == "customer_id"_t2)
    | inner_join<Payment, "t3">("order_id"_t1 == "order_id"_t3)
    | order_by("amount"_t3.desc())
    | to<std::vector<Consolidated>>;

  // Execute query and return results
  return query(conn).value();
}

}  // namespace join_orders_customers_payments
```

**Key implementation details:**

1. **Connection**: Uses `sqlite::connect("test_db.sqlite")` to connect to the database
2. **Table aliases**: Order is aliased as "t1", Customer as "t2", Payment as "t3"
3. **Column selection**: Uses user-defined literals (`_t1`, `_t2`, `_t3`) to reference columns from specific tables
4. **Column renaming**: Uses `as<"customer_name">` to rename the `name` column
5. **Inner joins**: Chains two `inner_join` operations with appropriate ON conditions
6. **Ordering**: Uses `.desc()` on the amount column for descending order
7. **Type conversion**: Uses `to<std::vector<Consolidated>>` to specify the return type
8. **Execution**: Calls the query with the connection and unwraps the result with `.value()`

