          rfl::internal::StringLiteral _alias>
struct OrderByWrapper<Desc<transpilation::Col<_name, _alias>>> {
  using ColType = transpilation::Col<_name, _alias>;
  constexpr static bool desc = true;
};

template <class... WrapperTypes>
struct OrderBy {};

