// Assuming PrimaryKey is defined in sqlgen library
template<typename T>
struct PrimaryKey {
  T value;
  operator T() const { return value; }
};

struct Supplier {
  PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the FULL JOIN query
  // SELECT s.name AS supplier_name, p.name AS product_name
  // FROM Supplier s
  // FULL JOIN Product p ON s.supplier_id = p.supplier_id
  auto query = select_from<Supplier, "s">(
      col<"name", "s"> | as<"supplier_name">,
      col<"name", "p"> | as<"product_name">
    )
    | full_join<Product, "p">(col<"supplier_id", "s"> == col<"supplier_id", "p">)
    | to<std::vector<SupProd>>;

  // Execute the query
  auto result = query(conn);

  // Return the results or empty vector if error
  if (result) {
    return *result;
  }

  return {};
}

}  // namespace full_join_suppliers_products
