  // Join condition: Post.user_id = User.id
  // Select columns: User.id, User.name, Post.title
  return mysql::to_sql(
    select_from<User, "t1">("id"_t1, "name"_t1, "title"_t2)
    | left_join<Post, "t2">("user_id"_t2 == "id"_t1)
  );
}

}  // namespace left_join_explicit
